using Entry=std::pair<QByteArray,QByteArray>;
void check(bool b){if(!b)throw std::runtime_error("test failure");}
template<class F>void rejects(F f){bool yes=false;try{f();}catch(const std::runtime_error&){yes=true;}check(yes);}
void word(QByteArray& b,unsigned v){b.append(char(v));b.append(char(v>>8));}void dword(QByteArray& b,unsigned v){word(b,v);word(b,v>>16);}
unsigned crc(const QByteArray& b){unsigned c=~0u;for(unsigned char ch:b){c^=ch;for(int j=0;j<8;++j)c=(c>>1)^((c&1)?0xedb88320u:0);}return ~c;}
QByteArray zip(const std::vector<Entry>& entries){QByteArray b,central;for(const auto& [name,data]:entries){auto offset=b.size();auto sum=crc(data);dword(b,0x04034b50);word(b,20);word(b,0);word(b,0);dword(b,0);dword(b,sum);dword(b,data.size());dword(b,data.size());word(b,name.size());word(b,0);b+=name;b+=data;dword(central,0x02014b50);word(central,20);word(central,20);word(central,0);word(central,0);dword(central,0);dword(central,sum);dword(central,data.size());dword(central,data.size());word(central,name.size());word(central,0);word(central,0);word(central,0);word(central,0);dword(central,0);dword(central,offset);central+=name;}auto offset=b.size();b+=central;dword(b,0x06054b50);word(b,0);word(b,0);word(b,entries.size());word(b,entries.size());dword(b,central.size());dword(b,offset);word(b,0);return b;}
int main(){try{QTemporaryDir dir;check(dir.isValid());auto path=dir.path()+"/book.epub";auto write=[&](const QByteArray& b){QFile f(path);check(f.open(QIODevice::WriteOnly));check(f.write(b)==b.size());};std::vector<Entry> valid{{"mimetype","application/epub+zip"},{"META-INF/container.xml","<container><rootfiles><rootfile full-path=\"book.opf\" media-type=\"application/oebps-package+xml\"/></rootfiles></container>"},{"book.opf","<package/>"},{"page.xhtml","<html><body>Hello</body></html>"}};auto run=[&]{library::validateDocumentContainer(path.toStdString(),"epub");};write(zip(valid));run();for(const QByteArray& name:std::vector<QByteArray>{"../escape","/absolute","a\\b",QByteArray("a\0b",3),"C:drive"}){auto e=valid;e.push_back({name,"x"});write(zip(e));rejects(run);}for(const QByteArray& text:std::vector<QByteArray>{"<html><script>alert(1)</script></html>","<html><img src=\"https://example.test/x\"/></html>","<html><body onclick=\"x\"/></html>","<!DOCTYPE html [<!ENTITY x 'x'>]><html>&x;</html>","<html><style>@import 'x';</style></html>"}){auto e=valid;e.back().second=text;write(zip(e));rejects(run);}auto e=valid;e[0].second="wrong";write(zip(e));rejects(run);e=valid;e[1].second="<container/>";write(zip(e));rejects(run);e=valid;e.push_back(e.back());write(zip(e));rejects(run);e=valid;e.push_back({"huge",QByteArray(16777217,'x')});write(zip(e));rejects(run);e=valid;for(int i=0;i<4093;++i)e.push_back({QByteArray::number(i),""});write(zip(e));rejects(run);e=valid;for(int i=0;i<17;++i)e.push_back({"expanded"+QByteArray::number(i),"x"});auto bomb=zip(e);for(int p=0;p+46<bomb.size();++p)if(bomb.mid(p,4)==QByteArray::fromHex("504b0102")){bomb[p+24]=0;bomb[p+25]=0;bomb[p+26]=0;bomb[p+27]=1;}write(bomb);rejects(run);{QFile oversized(path);check(oversized.open(QIODevice::WriteOnly));check(oversized.resize(67108865));}rejects([&]{library::validateDocumentContainer(path.toStdString(),"pdf");});write("%PDF-1.7\n");library::validateDocumentContainer(path.toStdString(),"pdf");rejects([&]{library::validateDocumentContainer(path.toStdString(),"docx");});QFile::remove(dir.path()+"/link");check(QFile::link(path,dir.path()+"/link"));rejects([&]{library::validateDocumentContainer((dir.path()+"/link").toStdString(),"pdf");});std::cout<<"document container tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
